10	/// Unified drawing component that supports multiple rendering methods:
11	/// sprites, text, nine-patch, and mesh (vertex buffer) rendering.
12	/// </summary>
13	public class DrawComponent
14	{
15	    public DrawElementType Type;
16	    public RenderTargetID Target;
17	
18	    // TransformComponent fields for all types
19	    public Vector2 Position;
20	    public float Rotation;
21	    public Vector2 Origin;
22	    public Vector2 Scale = Vector2.One;
23	    public Color Color = Color.White;
24	    public float LayerDepth;
25	
26	    // Sprite specific
27	    public Texture2D? Texture;
28	    public Rectangle? SourceRectangle;
29	    public Vector2 Size;
30	
31	    // Text specific
32	    public BitmapFont? Font;
33	    public string? Text;
34	    public bool Underline; // When true, MasterRenderSystem strokes a thin underline (in Color) under each text line (see the text render path).
35	    public float LineSpacing = DynamicTextComponent.DefaultLineSpacing; // Multiplier on Font.LineHeight when laying out '\n'-separated lines (see MasterRenderSystem).
36	
37	    // NinePatch specific
38	    public NinePatchInfo? NinePatchData;
39	
40	    // Mesh specific (for vertex buffer rendering)
41	    public VertexPositionColor[]? Vertices;
42	    public int[]? Indices;
43	    public PrimitiveType PrimitiveType = PrimitiveType.TriangleList;
44	    public Matrix? WorldMatrix; // TransformComponent matrix for mesh rendering
45	
46	    // 16-bit index cache for Reach-safe mesh rendering — see Get16BitIndices().
47	    private int[]? _indices16Source;
48	    private short[]? _indices16;
49	
50	    /// <summary>
51	    /// The mesh <see cref="Indices"/> as 16-bit values, for rendering through the
52	    /// <c>short[]</c> overload of <c>DrawUserIndexedPrimitives</c>. Returns <c>null</c> when there
53	    /// are no indices, or when the mesh has more vertices than a 16-bit index can address
54	    /// (more than 65536) — in which case the caller must fall back to the 32-bit
55	    /// <see cref="Indices"/> (valid only on the HiDef profile).
56	    /// <para>
57	    /// Why: the overload's index-array type selects the GPU index width (<c>int[]</c> ⇒ 32-bit,
58	    /// <c>short[]</c> ⇒ 16-bit), and the Reach profile (WebGL ES2 / BlazorGL) rejects 32-bit
59	    /// indices with <c>"Reach profile does not support 32 bit indices"</c>. Procedural meshes are
60	    /// tiny (far below the 16-bit ceiling), so rendering them through 16-bit indices works on
61	    /// every profile with no profile branch — the mesh analog of the sprite-run flush
62	    /// (see <see cref="MonoDreams.System.Draw.SpriteBatchFlush"/>).
63	    /// </para>
64	    /// The converted array is cached and rebuilt only when <see cref="Indices"/> is reassigned
65	    /// (reference identity changes), so a static mesh converts once — the per-frame render loop
66	    /// allocates nothing and the heap stays flat.
67	    /// </summary>
68	    public short[]? Get16BitIndices()
69	    {
70	        if (Indices is not { Length: > 0 }) return null;
71	        // A 16-bit index addresses vertices 0..65535, so up to 65536 vertices fit.
72	        if (Vertices is { Length: > ushort.MaxValue + 1 }) return null;
73	
74	        if (!ReferenceEquals(_indices16Source, Indices))
75	        {
76	            // Reuse the buffer when the new index array is the same length (common for an
77	            // animated mesh that rewrites its indices in place each frame).
78	            if (_indices16 is not { } buffer || buffer.Length != Indices.Length)
79	                buffer = new short[Indices.Length];
80	            for (var i = 0; i < Indices.Length; i++)
81	                buffer[i] = (short)Indices[i]; // values ≤ 65535 round-trip as ushort bit patterns
82	            _indices16 = buffer;
83	            _indices16Source = Indices;
84	        }
85	        return _indices16;
86	    }
87	
88	    /// <summary>
89	    /// Sets the mesh data from a MeshData struct.
90	    /// </summary>
91	    public void SetMeshData(MeshData meshData)
92	    {
93	        Type = DrawElementType.Mesh;
94	        Vertices = meshData.Vertices;
95	        Indices = meshData.Indices;
96	        PrimitiveType = meshData.PrimitiveType;
97	    }
98	
99	    /// <summary>
100	    /// Sets the mesh data from a mesh generator.
101	    /// </summary>
102	    public void SetMeshData(IMeshGenerator generator)
103	    {
104	        SetMeshData(generator.Generate());
105	    }
106	
107	    /// <summary>
108	    /// Gets the primitive count for mesh rendering.
109	    /// </summary>
110	    public int GetPrimitiveCount()
111	    {
112	        if (Indices == null || Indices.Length == 0) return 0;
113	
114	        return PrimitiveType switch
115	        {
116	            PrimitiveType.TriangleList => Indices.Length / 3,
117	            PrimitiveType.TriangleStrip => Indices.Length - 2,
118	            PrimitiveType.LineList => Indices.Length / 2,
119	            PrimitiveType.LineStrip => Indices.Length - 1,
120	            _ => 0
121	        };
122	    }
123	
124	    public bool HasValidMesh => Vertices is { Length: > 0 } && Indices is { Length: > 0 };
125	}
