18	/// <summary>
19	/// Guards the rendering premise "Sprite facing/orientation is a flip flag, not mirrored art".
20	/// A sprite's facing is <c>SpriteInfoComponent.FlipHorizontally</c> / <c>FlipVertically</c>, copied by
21	/// <c>SpritePrepSystem</c> into the <c>DrawComponent</c> and OR-composed into <c>SpriteEffects</c> by
22	/// <see cref="MasterRenderSystem.ComputeSpriteEffects"/> — so no sheet bakes a mirrored row for the
23	/// other facing. Two things the tests pin: the defaults compose to <see cref="SpriteEffects.None"/>
24	/// (unflagged sprites render byte-identical to before the flags existed), and the scene serializer
25	/// writes the keys ONLY when true (every committed pre-flip <c>.mdscene</c> stays byte-identical, which
26	/// the canonical-serialization fixed-point tests depend on).
27	///
28	/// Pure logic — a <see cref="World"/> and hand-built entities, no live <c>GraphicsDevice</c>.
29	/// </summary>
30	public class SpriteFlipTests
31	{
32	    // ---- (a) ComputeSpriteEffects: the four flag combinations ----
33	
34	    [Fact]
35	    public void ComputeSpriteEffects_NoFlags_IsNone_TheByteIdenticalDefault()
36	    {
37	        // The load-bearing case: an unflagged sprite must submit exactly what the renderer submitted
38	        // before the flags existed (SpriteEffects.None), so existing content is unchanged.
39	        var dc = SpriteDraw();
40	        Assert.False(dc.FlipHorizontally);
41	        Assert.False(dc.FlipVertically);
42	        Assert.Equal(SpriteEffects.None, MasterRenderSystem.ComputeSpriteEffects(dc));
43	    }
44	
45	    [Fact]
46	    public void ComputeSpriteEffects_HorizontalOnly_IsFlipHorizontally()
47	    {
48	        var dc = SpriteDraw();
49	        dc.FlipHorizontally = true;
50	        Assert.Equal(SpriteEffects.FlipHorizontally, MasterRenderSystem.ComputeSpriteEffects(dc));
51	    }
52	
53	    [Fact]
54	    public void ComputeSpriteEffects_VerticalOnly_IsFlipVertically()
55	    {
56	        var dc = SpriteDraw();
57	        dc.FlipVertically = true;
58	        Assert.Equal(SpriteEffects.FlipVertically, MasterRenderSystem.ComputeSpriteEffects(dc));
59	    }
60	
61	    [Fact]
62	    public void ComputeSpriteEffects_BothFlags_OrsTheTwoAxes()
63	    {
64	        var dc = SpriteDraw();
65	        dc.FlipHorizontally = true;
66	        dc.FlipVertically = true;
67	        Assert.Equal(SpriteEffects.FlipHorizontally | SpriteEffects.FlipVertically,
68	            MasterRenderSystem.ComputeSpriteEffects(dc));
69	    }
70	
71	    // ---- (b) Both flags default to false on a fresh component ----
72	
73	    [Fact]
74	    public void FreshComponents_DefaultBothFlagsFalse()
75	    {
76	        var sprite = new SpriteInfoComponent();
77	        Assert.False(sprite.FlipHorizontally);
78	        Assert.False(sprite.FlipVertically);
79	
80	        var draw = new DrawComponent();
81	        Assert.False(draw.FlipHorizontally);
82	        Assert.False(draw.FlipVertically);
83	    }
84	
85	    // ---- (c) SpritePrepSystem copies both flags, and perturbs nothing else ----
86	
87	    [Fact]
88	    public void SpritePrepSystem_CopiesBothFlags_ToTheDrawComponent()
89	    {
90	        using var world = new World();
91	        var entity = NewSpriteEntity(world, flipH: true, flipV: true);
92	
93	        RunPrep(world);
94	
95	        var draw = entity.Get<DrawComponent>();
96	        Assert.True(draw.FlipHorizontally);
97	        Assert.True(draw.FlipVertically);
98	    }
99	
100	    [Fact]
101	    public void SpritePrepSystem_UnflaggedSprite_LeavesBothFlagsFalse()
102	    {
103	        using var world = new World();
104	        var entity = NewSpriteEntity(world, flipH: false, flipV: false);
105	        // Start from a DrawComponent that was flipped on a previous frame: the copy must CLEAR it,
106	        // not leave a stale flip on a sprite whose facing changed back.
107	        entity.Get<DrawComponent>().FlipHorizontally = true;
108	        entity.Get<DrawComponent>().FlipVertically = true;
109	
110	        RunPrep(world);
111	
112	        var draw = entity.Get<DrawComponent>();
113	        Assert.False(draw.FlipHorizontally);
114	        Assert.False(draw.FlipVertically);
115	    }
116	
117	    [Fact]
118	    public void SpritePrepSystem_Flips_DoNotPerturbTheTransformFields()
119	    {
120	        // A flip mirrors the pixels INSIDE the destination rect — it must not move the drawn quad, so
121	        // every transform-ish field prep writes must be identical with the flags on and off. (This is
122	        // what keeps the drawn quad equal to GizmoTransform.SpriteWorldQuad's hit-test quad.)
123	        using var unflippedWorld = new World();
124	        var unflipped = NewSpriteEntity(unflippedWorld, flipH: false, flipV: false);
125	        RunPrep(unflippedWorld);
126	        var expected = unflipped.Get<DrawComponent>();
127	
128	        using var flippedWorld = new World();
129	        var flipped = NewSpriteEntity(flippedWorld, flipH: true, flipV: true);
130	        RunPrep(flippedWorld);
131	        var actual = flipped.Get<DrawComponent>();
132	
133	        Assert.Equal(expected.Position, actual.Position);
134	        Assert.Equal(expected.Rotation, actual.Rotation);
135	        Assert.Equal(expected.Origin, actual.Origin);
136	        Assert.Equal(expected.Scale, actual.Scale);
137	        Assert.Equal(expected.Size, actual.Size);
138	        Assert.Equal(expected.SourceRectangle, actual.SourceRectangle);
139	        Assert.Equal(expected.Color, actual.Color);
140	        Assert.Equal(expected.LayerDepth, actual.LayerDepth);
141	        // ...and the draw scale (hence the drawn quad's extent) is the same too.
142	        Assert.Equal(MasterRenderSystem.ComputeSpriteScale(expected), MasterRenderSystem.ComputeSpriteScale(actual));
143	    }
